 const post=async(actor:"finance"|"director",path:string,body:unknown)=>{const r=await fetch(fixture.url+path,{method:"POST",headers:{authorization:`Bearer ${fixture.sessions[actor].accessToken}`,"content-type":"application/json"},body:JSON.stringify(body)});const value=await r.json();expect(r.status).toBe(201);return value;};
