 let fundReads=0,optionReads=0;
 page.on("request",request=>{const path=new URL(request.url()).pathname;if(request.method()==="GET"&&path==="/api/fund-accounts")fundReads++;if(request.method()==="GET"&&path.endsWith("/registration-options"))optionReads++;if(request.method()==="POST"&&path.endsWith("/registrations")){const body=request.postDataJSON() as {idempotencyKey:string;expectedRegistrationId:string;sourceAllocations:Array<{sourceBatchId:string}>;amountCents:string;paidAt:string};attempts.push({key:body.idempotencyKey,registrationId:body.expectedRegistrationId,sourceId:body.sourceAllocations[0]?.sourceBatchId ?? "",amountCents:body.amountCents,paidAt:body.paidAt});}});
