 await post("director",`/fund-accounts/registrations/${correction.id}/confirm`,{expectedApprovalInstanceId:correction.approvalInstanceId,idempotencyKey:"task16-cas-real-confirm",reviewNote:"以核对表确认本次余额，实付尚未登记"});
 const changed=(await get("finance","/fund-accounts")).accounts.find((row:{scopeKey:string})=>row.scopeKey==="company:company-b");
