 await expect(form.locator('[aria-label="实际付款日期"] input')).toHaveValue("2026-11-04");
 await expect(form.locator('[aria-label="来源分摊金额1"] input')).toHaveValue("40");
 expect(attempts).toHaveLength(1);expect(attempts[0].registrationId).toBe(initial.currentRegistrationId);
 expect((await get("keeper","/payment-executions/recorded-items")).total).toBe(0);
 writeFileSync(testInfo.outputPath("real-fund-revision-stale-draft-before-read.json"),JSON.stringify({initialRegistrationId:initial.currentRegistrationId,currentRegistrationId:changed.currentRegistrationId,correctionId:correction.id,reviewCanConfirm:review.canConfirm,attempts,fundReads,optionReads,formalCount:0},null,2));
 const reRead=form.getByRole("button",{name:"重新读取资金资料",exact:true});
 await expect(reRead).toBeVisible();
