 await expect(page.getByText("本次核对余额：¥110.0000；核对日期：2026-11-06",{exact:true})).toBeVisible();
 const submitted=page.waitForResponse(response=>response.request().method()==="POST"&&new URL(response.url()).pathname.endsWith("/registrations"));
 await page.getByRole("button",{name:"已核实并确认登记",exact:true}).click();
 expect((await submitted).status()).toBe(201);
 expect(attempts).toHaveLength(2);expect(attempts[1]).toMatchObject({key:attempts[0].key,registrationId:changed.currentRegistrationId,sourceId:changed.sources[0].id,amountCents:"4000",paidAt:"2026-11-04"});
 const final=await get("keeper","/payment-executions/recorded-items");expect(final.total).toBe(1);expect(final.items[0]).toMatchObject({amountCents:"4000",paidAt:"2026-11-04"});
 const formal=await get("keeper",`/payment-executions/results/${attempts[0].key}`);
