 const get=async(path:string)=>{const r=await fetch(fixture.url+path,{headers:{authorization:`Bearer ${fixture.sessions.keeper.accessToken}`}});expect(r.status).toBe(200);return r.json();};
 const initial=await get("/payment-executions/payment-a/registration-options");expect(initial.contractHistoryBasis.required).toBe(true);expect(initial.contractHistoryBasis.records[0].historicalPaidCents).toBe("4000");
